render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$y, y = cfg$x)) + ggplot2::geom_segment(ggplot2::aes_string(x = 0, xend = cfg$y, yend = cfg$x), colour = "#CBD5E1") + ggplot2::geom_point(colour = cfg$color %||% "#0A84FF", size = 3) + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = cfg$y, y = cfg$x); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
